// ============================================================================
// spi_maestro.v  -  SPI master, full duplex, N-bit frame, all 4 SPI modes
//
// Based on the SPI description of Leal-del Rio et al. (RCS 75, 2014):
//   CLK_3 ~ 3.6 MHz generated by the master, CS active low, transfer ends on
//   the rising edge of CS, MOSI master->slave, MISO slave->master.
//
// Fixes vs. paper:
//   * The paper states CPOL = CPHA = 1 (mode 3) but describes sampling on the
//     falling edge, which contradicts mode 3. Here CPOL/CPHA are parameters
//     and the standard definitions are used:
//        CPHA = 0 : sample on leading edge,  shift on trailing edge
//        CPHA = 1 : shift on leading edge,   sample on trailing edge
//        CPOL     : idle level of SCK
//   * SCK is generated with a clock-enable on clk_50 (no derived clock):
//        f_SCK = CLK_HZ / (2*HDIV),  default 50 MHz / 14 = 3.57 MHz
// ============================================================================
`timescale 1ns / 1ps

module spi_maestro #(
    parameter integer CLK_HZ = 50_000_000,
    parameter integer SCK_HZ = 3_600_000,
    parameter integer N      = 8,
    parameter         CPOL   = 1'b1,
    parameter         CPHA   = 1'b1
)(
    input  wire         clk_50,
    input  wire         rst_n,
    input  wire         start,
    input  wire [N-1:0] tx_data,
    output reg  [N-1:0] rx_data,
    output reg          busy,
    output reg          done,
    output reg          sck,       // CLK_3 in the paper
    output wire         mosi,
    input  wire         miso,
    output reg          cs_n
);
    localparam integer HDIV_R = (CLK_HZ + SCK_HZ) / (2 * SCK_HZ);   // rounded
    localparam integer HDIV   = (HDIV_R < 1) ? 1 : HDIV_R;
    localparam integer DW   = (HDIV > 1) ? $clog2(HDIV) : 1;
    localparam integer EW   = $clog2(2 * N + 2);

    reg [DW-1:0]  contador_div;
    reg [EW-1:0]  edge_cnt;          // number of SCK edges produced
    reg [N-1:0]   tx_sh, rx_sh;

    wire tick = (contador_div == HDIV - 1);
    assign mosi = cs_n ? 1'b0 : tx_sh[N-1];

    always @(posedge clk_50 or negedge rst_n)
        if (!rst_n)              contador_div <= 0;
        else if (!busy || tick)  contador_div <= 0;
        else                     contador_div <= contador_div + 1'b1;

    wire leading = ~edge_cnt[0];     // edges 0,2,4.. are leading edges

    always @(posedge clk_50 or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0; done <= 1'b0; sck <= CPOL; cs_n <= 1'b1;
            edge_cnt <= 0; tx_sh <= 0; rx_sh <= 0; rx_data <= 0;
        end else begin
            done <= 1'b0;
            if (!busy) begin
                sck <= CPOL;
                if (start) begin
                    busy <= 1'b1; cs_n <= 1'b0;   // CS low: enable slave
                    tx_sh <= tx_data; edge_cnt <= 0;
                end
            end else if (tick) begin
                if (edge_cnt < 2 * N) begin
                    sck      <= ~sck;
                    edge_cnt <= edge_cnt + 1'b1;
                    if (CPHA == 1'b0) begin
                        if (leading) rx_sh <= {rx_sh[N-2:0], miso};
                        else         tx_sh <= {tx_sh[N-2:0], 1'b0};
                    end else begin
                        if (leading) begin
                            if (edge_cnt != 0) tx_sh <= {tx_sh[N-2:0], 1'b0};
                        end else     rx_sh <= {rx_sh[N-2:0], miso};
                    end
                end else begin
                    cs_n    <= 1'b1;              // CS rising edge ends transfer
                    busy    <= 1'b0;
                    done    <= 1'b1;
                    rx_data <= rx_sh;
                end
            end
        end
    end
endmodule
